export function splitHangul(word) {
  // 한글 자모 분리 (간단 버전)
  const chosung = [
    "ㄱ","ㄲ","ㄴ","ㄷ","ㄸ","ㄹ","ㅁ","ㅂ","ㅃ","ㅅ","ㅆ","ㅇ","ㅈ","ㅉ","ㅊ","ㅋ","ㅌ","ㅍ","ㅎ"
  ];
  const jungsung = [
    "ㅏ","ㅐ","ㅑ","ㅒ","ㅓ","ㅔ","ㅕ","ㅖ","ㅗ","ㅘ","ㅙ","ㅚ","ㅛ","ㅜ","ㅝ","ㅞ","ㅟ","ㅠ","ㅡ","ㅢ","ㅣ"
  ];
  const jongsung = [
    "","ㄱ","ㄲ","ㄳ","ㄴ","ㄵ","ㄶ","ㄷ","ㄹ","ㄺ","ㄻ","ㄼ","ㄽ","ㄾ","ㄿ","ㅀ","ㅁ","ㅂ","ㅄ","ㅅ","ㅆ","ㅇ","ㅈ","ㅊ","ㅋ","ㅌ","ㅍ","ㅎ"
  ];

  // 복합 모음 분리 맵
  const complexVowelMap = {
    "ㅘ": ["ㅗ", "ㅏ"],
    "ㅙ": ["ㅗ", "ㅐ"],
    "ㅚ": ["ㅗ", "ㅣ"],
    "ㅝ": ["ㅜ", "ㅓ"],
    "ㅞ": ["ㅜ", "ㅔ"],
    "ㅟ": ["ㅜ", "ㅣ"],
    "ㅢ": ["ㅡ", "ㅣ"]
  };

  let result = [];
  for (let i = 0; i < word.length; i++) {
    const code = word.charCodeAt(i) - 0xAC00;
    if (code < 0 || code > 11171) {
      result.push(word[i]);
      continue;
    }
    const cho = Math.floor(code / 588);
    const jung = Math.floor((code - (cho * 588)) / 28);
    const jong = code % 28;
    result.push(chosung[cho]);
    // 복합 모음 분리
    const jungChar = jungsung[jung];
    if (complexVowelMap[jungChar]) {
      result.push(...complexVowelMap[jungChar]);
    } else {
      result.push(jungChar);
    }
    if (jongsung[jong] !== "") result.push(jongsung[jong]);
  }
  return result;
}
