import React, { useState, useEffect, useRef } from 'react';
import './game2048.css';

const GRID_SIZE = 6;
const INITIAL_TILES = 2;
const FALL_SPEED = 100; // 0.1초마다 한 칸씩 내려옴

const Game2048 = () => {
  const [board, setBoard] = useState([]);
  const [score, setScore] = useState(0);
  const [gameOver, setGameOver] = useState(false);
  const [bestScore, setBestScore] = useState(0);
  const [fallingTile, setFallingTile] = useState(null);
  const [fallingPosition, setFallingPosition] = useState(0);
  const gameLoopRef = useRef(null);

  // 초기 보드 생성
  const initializeBoard = () => {
    const newBoard = Array(GRID_SIZE).fill().map(() => Array(GRID_SIZE).fill(0));
    return newBoard;
  };

  // 새로운 타일 생성
  const createNewTile = () => {
    const value = Math.random() < 0.9 ? 2 : 4;
    const column = Math.floor(Math.random() * GRID_SIZE);
    return { value, column };
  };

  // 게임 초기화
  useEffect(() => {
    setBoard(initializeBoard());
    startGameLoop();
    return () => {
      if (gameLoopRef.current) {
        clearInterval(gameLoopRef.current);
      }
    };
  }, []);

  // 게임 루프 시작
  const startGameLoop = () => {
    if (gameLoopRef.current) {
      clearInterval(gameLoopRef.current);
    }
    gameLoopRef.current = setInterval(() => {
      if (!fallingTile) {
        setFallingTile(createNewTile());
        setFallingPosition(0);
      } else {
        moveFallingTileDown();
      }
    }, FALL_SPEED);
  };

  // 타일이 바닥이나 다른 타일에 닿았는지 확인
  const checkCollision = (position, column) => {
    // 바닥에 닿았는지 확인
    if (position >= GRID_SIZE - 1) return true;
    
    // 다른 타일에 닿았는지 확인
    if (board[position + 1][column] !== 0) return true;
    
    return false;
  };

  // 타일 아래로 이동
  const moveFallingTileDown = () => {
    if (!fallingTile) return;

    if (checkCollision(fallingPosition, fallingTile.column)) {
      placeFallingTile();
    } else {
      setFallingPosition(prev => prev + 1);
    }
  };

  // 타일 배치
  const placeFallingTile = () => {
    if (!fallingTile) return;

    const newBoard = [...board];
    newBoard[fallingPosition][fallingTile.column] = fallingTile.value;
    setBoard(newBoard);
    setFallingTile(null);
    setFallingPosition(0);

    // 같은 숫자 합치기 체크
    checkAndMergeTiles();
  };

  // 같은 숫자 합치기
  const checkAndMergeTiles = () => {
    const newBoard = [...board];
    let merged = false;
    let newScore = score;

    // 세로 방향 합치기
    for (let col = 0; col < GRID_SIZE; col++) {
      for (let row = GRID_SIZE - 1; row > 0; row--) {
        if (newBoard[row][col] !== 0 && newBoard[row][col] === newBoard[row - 1][col]) {
          newBoard[row][col] *= 2;
          newBoard[row - 1][col] = 0;
          newScore += newBoard[row][col];
          merged = true;
        }
      }
    }

    // 빈 공간 채우기
    for (let col = 0; col < GRID_SIZE; col++) {
      for (let row = GRID_SIZE - 1; row >= 0; row--) {
        if (newBoard[row][col] === 0) {
          for (let r = row - 1; r >= 0; r--) {
            if (newBoard[r][col] !== 0) {
              newBoard[row][col] = newBoard[r][col];
              newBoard[r][col] = 0;
              break;
            }
          }
        }
      }
    }

    if (merged) {
      setBoard(newBoard);
      setScore(newScore);
      if (newScore > bestScore) {
        setBestScore(newScore);
      }
    }

    // 게임 오버 체크
    if (checkGameOver(newBoard)) {
      setGameOver(true);
      clearInterval(gameLoopRef.current);
    }
  };

  // 게임 오버 체크
  const checkGameOver = (board) => {
    // 빈 칸이 있는지 확인
    for (let i = 0; i < GRID_SIZE; i++) {
      for (let j = 0; j < GRID_SIZE; j++) {
        if (board[i][j] === 0) return false;
      }
    }

    // 인접한 같은 숫자가 있는지 확인
    for (let i = 0; i < GRID_SIZE; i++) {
      for (let j = 0; j < GRID_SIZE; j++) {
        if (
          (i < GRID_SIZE - 1 && board[i][j] === board[i + 1][j]) ||
          (j < GRID_SIZE - 1 && board[i][j] === board[i][j + 1])
        ) {
          return false;
        }
      }
    }
    return true;
  };

  // 키보드 이벤트 처리
  useEffect(() => {
    const handleKeyDown = (e) => {
      if (gameOver || !fallingTile) return;

      switch (e.key) {
        case 'ArrowLeft':
          if (fallingTile.column > 0 && !checkCollision(fallingPosition, fallingTile.column - 1)) {
            setFallingTile(prev => ({ ...prev, column: prev.column - 1 }));
          }
          break;
        case 'ArrowRight':
          if (fallingTile.column < GRID_SIZE - 1 && !checkCollision(fallingPosition, fallingTile.column + 1)) {
            setFallingTile(prev => ({ ...prev, column: prev.column + 1 }));
          }
          break;
        case 'ArrowDown':
          moveFallingTileDown();
          break;
        default:
          break;
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [fallingTile, gameOver, fallingPosition]);

  // 게임 리셋
  const resetGame = () => {
    setBoard(initializeBoard());
    setScore(0);
    setGameOver(false);
    setFallingTile(null);
    setFallingPosition(0);
    startGameLoop();
  };

  return (
    <div className="game-container">
      <div className="header">
        <h1>2048</h1>
        <div className="scores">
          <div className="score-box">
            <span>Score</span>
            <span>{score}</span>
          </div>
          <div className="score-box">
            <span>Best</span>
            <span>{bestScore}</span>
          </div>
        </div>
        <button onClick={resetGame} className="new-game-button">
          New Game
        </button>
      </div>
      <div className="game-board">
        {board.map((row, i) => (
          <div key={i} className="row">
            {row.map((cell, j) => (
              <div key={j} className={`cell cell-${cell}`}>
                {cell !== 0 && cell}
              </div>
            ))}
          </div>
        ))}
        {fallingTile && (
          <div
            className={`falling-tile cell-${fallingTile.value}`}
            style={{
              left: `${fallingTile.column * 110}px`,
              top: `${fallingPosition * 110}px`,
            }}
          >
            {fallingTile.value}
          </div>
        )}
      </div>
      {gameOver && (
        <div className="game-over">
          <h2>Game Over!</h2>
          <button onClick={resetGame}>Try Again</button>
        </div>
      )}
    </div>
  );
};

export default Game2048;
