import React, { useState, useEffect, useRef } from "react";
import { splitHangul } from "./hangulUtil";
import { amber, deepPurple, grey, lightBlue } from "@mui/material/colors";
import { wordList } from "../data/wordList";

function WordGuessGame() {
  const [guesses, setGuesses] = useState([["", "", "", "", ""]]);
  const [currentRow, setCurrentRow] = useState(0);
  const [currentCol, setCurrentCol] = useState(0);
  const [success, setSuccess] = useState(false);
  const [answer, setAnswer] = useState("");
  const scriptElement = useRef(null);
  const inputRefs = useRef([]);
  const lastRow = 6;

  useEffect(() => {
    // 초기 정답 설정
    const randomIndex = Math.floor(Math.random() * wordList.length);
    setAnswer(wordList[randomIndex]);
  }, []);

  useEffect(() => {
    const script = document.createElement("script");
    script.setAttribute("src", "https://t1.daumcdn.net/kas/static/ba.min.js");
    script.setAttribute("charset", "utf-8");
    script.setAttribute("async", "true");
    scriptElement.current?.appendChild(script);
  }, [answer]);

  const handleKeyDown = (e, rowIdx, colIdx) => {
    if (rowIdx !== currentRow) return;

    if (e.key === "Enter") {
      if (guesses[currentRow].every(char => char !== "")) {
        const currentGuess = guesses[currentRow].join("");
        const splitWord = splitHangul(answer).join("");

        setCurrentRow(prev => prev + 1);
        setCurrentCol(0);
        setGuesses(prev => [...prev, ["", "", "", "", ""]]);

        if (currentGuess === splitWord) {
          setSuccess(true);
        } else {
          if (currentRow === lastRow) {
            setSuccess(false);
          }
        }
      }
    } else if (e.key === "Backspace") {
      const newGuesses = [...guesses];
      if (guesses[rowIdx][colIdx] === "") {
        if (colIdx > 0) {
          setCurrentCol(colIdx - 1);
          newGuesses[rowIdx][colIdx - 1] = "";
          setGuesses(newGuesses);
          inputRefs.current[rowIdx * 5 + colIdx - 1]?.focus();
        }
      } else {
        newGuesses[rowIdx][colIdx] = "";
        setGuesses(newGuesses);
      }
    }
  };

  const handleInput = (e, rowIdx, colIdx) => {
    const value = e.target.value;
    if (value.length > 0) {
      const newGuesses = [...guesses];
      newGuesses[rowIdx][colIdx] = value[value.length - 1];
      setGuesses(newGuesses);

      if (colIdx < 4) {
        setCurrentCol(colIdx + 1);
        inputRefs.current[rowIdx * 5 + colIdx + 1]?.focus();
      }
    }
  };

  const handleRestart = () => {
    // 새로운 랜덤 정답 선택
    const randomIndex = Math.floor(Math.random() * wordList.length);
    setAnswer(wordList[randomIndex]);
    
    // 게임 상태 초기화
    setGuesses([["", "", "", "", ""]]);
    setCurrentRow(0);
    setCurrentCol(0);
    setSuccess(false);
  };

  const answerSplit = splitHangul(answer);

  return (
    <div style={{ 
      display: "flex", 
      flexDirection: "column", 
      alignItems: "center", 
      justifyContent: "center",
      minHeight: "100vh",
      padding: "20px"
    }}>
      <div style={{
        marginBottom: "40px",
        textAlign: "center",
        color: "#333",
        maxWidth: "600px",
        lineHeight: "1.6"
      }}>
        <h2 style={{ 
          color: deepPurple[500],
          marginBottom: "20px",
          fontSize: "24px"
        }}>
          게임 설명
        </h2>
        <ol style={{
          listStyleType: "decimal",
          paddingLeft: "20px",
          textAlign: "left"
        }}>
          <li>자음과 모음을 분리했을 때 5글자가 되는 단어</li>
          <li>쌍자음, 복합 모음은 입력 불가</li>
          <li>각 칸에 옳은 글자가 들어가면 보라색으로 표시</li>
        </ol>
      </div>
      <div style={{ 
        marginBottom: 20,
        display: "flex",
        flexDirection: "column",
        alignItems: "center"
      }}>
        {[...Array(6)].map((_, rowIdx) => {
          const guess = guesses[rowIdx] || [];
          return (
            <div key={rowIdx} style={{ display: "flex", gap: 8, marginBottom: 4 }}>
              {[...Array(5)].map((_, colIdx) => {
                const char = guess[colIdx] || "";
                let borderColor = deepPurple[500];
                let backgroundColor = "#ffffff";
                
                if (rowIdx < currentRow) {
                  if (char === answerSplit[colIdx]) {
                    borderColor = deepPurple[400];
                    backgroundColor = deepPurple[400];
                  } else {
                    if (answerSplit.includes(char)) {
                      borderColor = lightBlue[400];
                      backgroundColor = lightBlue[400];
                    } else {
                      borderColor = grey[400];
                      backgroundColor = grey[400];
                    }
                  }
                }

                return (
                  <input
                    key={colIdx}
                    ref={el => inputRefs.current[rowIdx * 5 + colIdx] = el}
                    value={char}
                    onChange={(e) => handleInput(e, rowIdx, colIdx)}
                    onKeyDown={(e) => handleKeyDown(e, rowIdx, colIdx)}
                    style={{
                      width: 40,
                      height: 40,
                      border: `2px solid ${borderColor}`,
                      textAlign: "center",
                      fontSize: 24,
                      boxSizing: "border-box",
                      background: backgroundColor,
                      color: rowIdx < currentRow ? "#ffffff" : "#000000",
                      textTransform: "uppercase",
                      borderRadius: "4px",
                      transition: "all 0.2s ease-in-out",
                    }}
                    maxLength={1}
                    disabled={rowIdx !== currentRow}
                  />
                );
              })}
            </div>
          );
        })}
      </div>
      {success && (
        <div
          style={{
            position: "fixed",
            top: "10%",
            left: "50%",
            transform: "translate(-50%, -50%)",
            background: "white",
            border: "2px solid #4caf50",
            padding: 40,
            fontSize: 32,
            color: "#4caf50",
            zIndex: 1000,
          }}
        >
          정답입니다!
        </div>
      )}
      {(currentRow === lastRow || success) && (
        <div style={{ marginTop: 32, textAlign: "center" }}>
          <button
            onClick={handleRestart}
            style={{
              padding: "10px 20px",
              fontSize: "18px",
              backgroundColor: deepPurple[500],
              color: "white",
              border: "none",
              borderRadius: "4px",
              cursor: "pointer",
              transition: "background-color 0.2s",
            }}
            onMouseOver={(e) => e.target.style.backgroundColor = deepPurple[400]}
            onMouseOut={(e) => e.target.style.backgroundColor = deepPurple[500]}
          >
            게임 다시 시작하기
          </button>
        </div>
      )}
      {(currentRow === lastRow) && !success && (
        <div style={{ marginTop: 32, textAlign: "center", color: "#888", fontSize: 18 }}>
          정답은 {answer} 입니다. 다시 시도해보세요.
        </div>
      )}
      <div style={{ marginTop: 32, textAlign: "center" }} ref={scriptElement}>
        <ins
          className="kakao_ad_area"
          style={{ display: "none" }}
          data-ad-unit="DAN-hsPJu5SU6nUfFFLZ"
          data-ad-width="320"
          data-ad-height="50"
        ></ins>
      </div>
    </div>
  );
}

export default WordGuessGame;
